// Remove Invalid Products | Mode: Run Once for All Items
// Course interface: filteredProducts, totalFiltered, classificationSummary.
// Keeps products the judge labelled "match" with confidence high or medium. Everything the AI returns is
// validated here, and products are matched by the id sent in the prompt (not by long URLs).
//   AI service failed      -> nothing passes, errorReason "ai_unavailable"
//   Answer is not readable -> fail open: all products pass, classificationStatus "parse_failed"
//   Zero products pass     -> errorReason "no_valid_products"
const STATUSES = ['match', 'no_match', 'uncertain'];
const CONFIDENCES = ['high', 'medium', 'low'];

const products = Array.isArray($('Reshape Amazon Response').first().json.amazonProducts) ? $('Reshape Amazon Response').first().json.amazonProducts : [];
const key = $('Get Category Key').first().json;
const withId = (p, id) => ({ ...p, id });
const parseJson = (text) => {
  const t = String(text).replace(/```(?:json)?/gi, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
};
const result = (extra) => [{ json: { selectedCategory: key.selectedCategory, categoryKey: key.categoryKey, classificationStatus: 'ok', errorReason: null,
  filteredProducts: [], totalFiltered: 0, removedProducts: [], classificationSummary: { total: products.length, matches: 0, no_matches: 0, uncertain: 0, unclassified: 0 }, ...extra } }];

const ai = $input.first().json;
if (ai.error !== undefined || typeof ai.output !== 'string' || ai.output.trim() === '') {
  return result({ classificationStatus: 'ai_unavailable', errorReason: 'ai_unavailable',
    removedProducts: products.map((p, i) => ({ id: i, name: p.name, reason: 'ai_unavailable' })) });
}
const parsed = parseJson(ai.output);
if (!parsed || !Array.isArray(parsed.classifications)) {
  return result({ classificationStatus: 'parse_failed', filteredProducts: products.map(withId), totalFiltered: products.length,
    warning: 'The category judge answer could not be read; products were not filtered.' });
}

const idByUrl = new Map(products.map((p, i) => [p.url, i]));
const byId = new Map();
for (const c of parsed.classifications) {
  if (!c || typeof c !== 'object') continue;
  const id = Number.isInteger(c.id) ? c.id : idByUrl.get(c.url);
  if (Number.isInteger(id) && id >= 0 && id < products.length && !byId.has(id)) byId.set(id, c);
}
const summary = { total: products.length, matches: 0, no_matches: 0, uncertain: 0, unclassified: 0 };
const kept = [];
const removed = [];
products.forEach((p, i) => {
  const c = byId.get(i);
  const status = c && STATUSES.includes(c.match_status) ? c.match_status : null;
  const confidence = c && CONFIDENCES.includes(c.confidence) ? c.confidence : 'low';
  if (!status) summary.unclassified += 1;
  else if (status === 'match') summary.matches += 1;
  else if (status === 'no_match') summary.no_matches += 1;
  else summary.uncertain += 1;
  if (status === 'match' && confidence !== 'low') {
    kept.push({ ...withId(p, i), classification_reasoning: String(c.reasoning || '').replace(/\s+/g, ' ').trim().slice(0, 200) });
  } else {
    removed.push({ id: i, name: p.name, reason: !status ? 'not_classified' : status === 'match' ? 'low_confidence' : status });
  }
});
return result({ filteredProducts: kept, totalFiltered: kept.length, removedProducts: removed, classificationSummary: summary,
  errorReason: kept.length === 0 ? 'no_valid_products' : null });

// Save Standardized Data | Mode: Run Once for All Items
// Course interface: attributeData ({ products, summary }), products, summary.
// The AI only labels text attributes from a fixed vocabulary; everything else is computed here:
// values are validated (anything else becomes "unknown"), every attribute must be SUPPORTED by a keyword in the
// product's own text (otherwise it is rejected as a guess), size is parsed from the title, price and rating are
// parsed as numbers, the price bucket and every summary count are computed by code.
const VOCAB = {"material":["wool","cotton","jute","polyester","polypropylene","nylon","viscose","microfiber","chenille","acrylic","faux_fur","blend","synthetic","other","unknown"],"construction":["flatweave","hand_tufted","machine_tufted","hand_knotted","power_loomed","braided","other","unknown"],"pile":["flat","low","medium","high","shag","unknown"],"colors":["cream","white","gray","charcoal","beige","taupe","brown","blue","navy","teal","green","red","orange","pink","purple","multi","black","gold","ivory","tan","olive","yellow","mustard","terracotta","other"],"pattern":["solid","geometric","floral","abstract","medallion","striped","moroccan","distressed","braided","textured","oriental","tribal","chevron","trellis","other","unknown"],"style":["modern","traditional","transitional","bohemian","farmhouse","coastal","minimalist","vintage","contemporary","industrial","mid_century","glam","rustic","other","unknown"],"shape":["rectangle","round","square","oval","runner","other","unknown"],"size_class":["small","medium","large","xl","runner","unknown"],"features":["washable","non_slip","stain_resistant","water_resistant","uv_resistant","indoor_outdoor","soft_plush","handmade","eco_friendly"]};
const SINGLE = ['construction', 'pile', 'pattern', 'style', 'shape', 'size_class'];
const MULTI = { material: 3, colors: 3, features: 6 };
const FACETS = [...Object.keys(MULTI), ...SINGLE];
const ALIASES = { pile: { flatweave: 'flat', low_pile: 'low', medium_pile: 'medium', high_pile: 'high' }, colors: { grey: 'gray', charcoal_gray: 'charcoal', charcoal_grey: 'charcoal' } };
const PILE_LABEL = { flat: 'Flatweave', low: 'Low-pile', medium: 'Medium-pile', high: 'High-pile', shag: 'Shag' };
const label = (facet, v) => {
  if (!v || v === 'unknown' || v === 'other') return 'Unknown';
  if (facet === 'pile') return PILE_LABEL[v] || 'Unknown';
  if (v === 'mid_century') return 'Mid-Century';
  return v.split('_').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
};

// Keyword evidence: an attribute value is kept only if the product text contains a word that states it.
const KW = {
  material: { wool: /\bwool(?:en)?\b|\bmerino\b/, cotton: /\bcotton\b/, jute: /\bjute\b/, polyester: /\bpolyester\b|\bpoly\b/, polypropylene: /\bpolypropylene\b|\bolefin\b/,
    nylon: /\bnylon\b/, viscose: /\bviscose\b|\brayon\b|\bbamboo silk\b/, microfiber: /\bmicrofib(?:er|re)\b/, chenille: /\bchenille\b/, acrylic: /\bacrylic\b/,
    faux_fur: /\bfaux[- ]fur\b/, blend: /\bblend(?:ed)?\b/, synthetic: /\bsynthetic\b/ },
  construction: { flatweave: /\bflat[- ]?weave\b|\bflat[- ]woven\b|\bkilim\b|\bdhurrie\b/, hand_tufted: /\bhand[- ]?tufted\b/, machine_tufted: /\bmachine[- ]?tufted\b/,
    hand_knotted: /\bhand[- ]?knotted\b/, power_loomed: /\bpower[- ]?loomed\b|\bmachine[- ](?:woven|made)\b/, braided: /\bbraided\b/ },
  pile: { flat: /\bflat[- ]?weave\b|\bultra[- ]?thin\b|\bflat\b/, low: /\blow[- ]?(?:pile|profile)\b|\bshort[- ]?pile\b|\bthin\b/, medium: /\bmedium[- ]?pile\b|\bmid[- ]?pile\b/,
    high: /\bhigh[- ]?pile\b|\bthick pile\b/, shag: /\bshag(?:gy)?\b|\bfluffy\b|\blong[- ]?pile\b|\bfuzzy\b/ },
  pattern: { solid: /\bsolid\b/, geometric: /\bgeometric\b|\bdiamond\b|\blattice\b|\bhexagon\b|\bmaze\b/, floral: /\bfloral\b|\bflowers?\b|\bbotanical\b|\bleaf\b|\bleaves\b/,
    abstract: /\babstract\b|\bwatercolou?r\b|\bbrush ?stroke\b/, medallion: /\bmedallion\b/, striped: /\bstrip(?:e|ed|es)\b/, moroccan: /\bmoroccan\b/,
    distressed: /\bdistressed\b|\bfaded\b|\bweathered\b/, braided: /\bbraided\b/, textured: /\btextur(?:ed|e)\b|\bhigh[- ]?low\b|\bcarved\b|\braised\b/,
    oriental: /\borient(?:al)?\b|\bpersian\b|\bturkish\b|\bheriz\b/, tribal: /\btribal\b|\bkilim\b|\baztec\b|\bsouthwestern\b/, chevron: /\bchevron\b|\bherringbone\b|\bzig-?zag\b/,
    trellis: /\btrellis\b|\bquatrefoil\b|\blattice\b/ },
  style: { modern: /\bmodern\b/, traditional: /\btraditional\b|\bclassic\b/, transitional: /\btransitional\b/, bohemian: /\bboho\b|\bbohemian\b/, farmhouse: /\bfarmhouse\b|\bcottage\b/,
    coastal: /\bcoastal\b|\bbeach\b|\bnautical\b/, minimalist: /\bminimali(?:st|stic)\b|\bminimal\b/, vintage: /\bvintage\b|\bretro\b|\bantique\b/, contemporary: /\bcontemporary\b/,
    industrial: /\bindustrial\b/, mid_century: /\bmid[- ]?century\b|\bmcm\b/, glam: /\bglam\b|\bluxe\b/, rustic: /\brustic\b/ },
  colors: { cream: /\bcream\b/, white: /\bwhite\b/, gray: /\bgr[ae]y\b|\bsilver\b/, charcoal: /\bcharcoal\b/, beige: /\bbeige\b|\boatmeal\b|\bsand\b/, taupe: /\btaupe\b/,
    brown: /\bbrown\b|\bchocolate\b|\bcoffee\b/, blue: /\bblue\b|\bdenim\b|\baqua\b/, navy: /\bnavy\b/, teal: /\bteal\b|\bturquoise\b/, green: /\bgreen\b|\bsage\b|\bemerald\b|\bforest\b/,
    red: /\bred\b|\bburgundy\b|\bwine\b/, orange: /\borange\b|\brust\b/, pink: /\bpink\b|\bblush\b|\brose\b/, purple: /\bpurple\b|\blavender\b|\bviolet\b|\bplum\b/,
    multi: /\bmulti[- ]?colou?r(?:ed)?\b|\bcolou?rful\b/, black: /\bblack\b|\bebony\b/, gold: /\bgold\b/, ivory: /\bivory\b/, tan: /\btan\b|\bcamel\b/, olive: /\bolive\b/,
    yellow: /\byellow\b/, mustard: /\bmustard\b|\bochre\b/, terracotta: /\bterra ?cotta\b/ },
  features: { washable: /\bwashable\b|\bmachine[- ]wash/, non_slip: /\bnon[- ]?slip\b|\banti[- ]?(?:slip|skid)\b|\bskid\b|\bgrip\b/, stain_resistant: /\bstain[- ]?(?:resistant|proof)\b/,
    water_resistant: /\bwater[- ]?(?:resistant|proof|repellent)\b|\bwaterproof\b/, uv_resistant: /\buv\b|\bfade[- ]?(?:resistant|proof)\b/, indoor_outdoor: /\bindoor[\s/-]*outdoor\b/,
    soft_plush: /\bsoft\b|\bplush\b|\bfluffy\b/, handmade: /\bhand[- ]?(?:made|tufted|knotted|woven|loomed)\b/, eco_friendly: /\beco\b|\bsustainable\b|\brecycled\b/ },
};
const supported = (facet, value, text) => {
  const re = KW[facet] && KW[facet][value];
  if (!re) return true;                                           // other / unknown / no rule
  if (re.test(text)) return true;
  return facet === 'pile' && /\bpile\b/.test(text) && /\d/.test(text);   // numeric pile heights ("0.75 inch pile") are read by the AI
};

const upstream = $('Remove Invalid Products').first().json;
const products = upstream.filteredProducts || [];
const base = { selectedCategory: upstream.selectedCategory, categoryKey: $('Get Category Key').first().json.categoryKey,
  standardizationStatus: 'ok', errorReason: null, attributeData: null, products: [], summary: {},
  standardizedProducts: [], attributeSummary: {}, attributeCoverage: {}, priceStats: null, invalidValues: 0, unsupportedValues: 0, unsupportedExamples: [] };

if (products.length === 0) return [{ json: { ...base, standardizationStatus: 'skipped', errorReason: upstream.errorReason || 'no_valid_products' } }];

const parseJson = (text) => {
  const t = String(text).replace(/```(?:json)?/gi, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
};
const ai = $input.first().json;
let status = 'ok';
let items = [];
if (ai.error !== undefined || typeof ai.output !== 'string' || ai.output.trim() === '') status = 'ai_unavailable';
else {
  const parsed = parseJson(ai.output);
  if (parsed && Array.isArray(parsed.items)) items = parsed.items; else status = 'parse_failed';
}
if (status !== 'ok') {
  return [{ json: { ...base, standardizationStatus: status, error: 'Failed to parse attributes',
    errorReason: status === 'ai_unavailable' ? 'ai_unavailable' : 'ai_output_invalid' } }];
}

const norm = (facet, v) => { const n = String(v ?? '').trim().toLowerCase().replace(/[\s-]+/g, '_'); return (ALIASES[facet] && ALIASES[facet][n]) || n; };
let invalid = 0;
let unsupported = 0;
const unsupportedExamples = [];
const reject = (id, facet, value) => { unsupported += 1; if (unsupportedExamples.length < 10) unsupportedExamples.push({ id, facet, value }); };
const pickOne = (facet, v, text, id) => {
  const n = norm(facet, v);
  if (!VOCAB[facet].includes(n)) { if (n !== '') invalid += 1; return 'unknown'; }
  if (!supported(facet, n, text)) { reject(id, facet, n); return 'unknown'; }
  return n;
};
const pickMany = (facet, v, text, id) => {
  const out = [];
  for (const x of Array.isArray(v) ? v : v == null || v === '' ? [] : [v]) {
    const n = norm(facet, x);
    if (!VOCAB[facet].includes(n)) invalid += 1;
    else if (!supported(facet, n, text)) reject(id, facet, n);
    else if (!out.includes(n)) out.push(n);
  }
  return out.slice(0, MULTI[facet]);
};
const num = (v) => { const m = String(v ?? '').replace(/,/g, '').match(/\d+(?:\.\d+)?/); return m ? Number(m[0]) : null; };
const sizeOf = (name) => {
  const m = String(name || '').toLowerCase().match(/(\d{1,2}(?:\.\d)?)\s*(?:ft|feet|foot|')?\s*(?:x|×|by)\s*(\d{1,2}(?:\.\d)?)\s*(?:ft|feet|foot|')?/);
  return m ? `${Number(m[1])}'×${Number(m[2])}'` : 'Unknown';
};
const bucketOf = (p) => (p === null ? 'Unknown' : p < 50 ? 'Under $50' : p < 100 ? '$50-100' : p < 200 ? '$100-200' : p < 500 ? '$200-500' : '$500+');

const byId = new Map();
for (const it of items) if (it && Number.isInteger(it.id) && !byId.has(it.id)) byId.set(it.id, it);
const standardized = products.map((p) => {
  const it = byId.get(p.id) || {};
  const text = [p.name, p.pattern, ...(Array.isArray(p.details) ? p.details : [])].join(' ').toLowerCase();
  const row = { id: p.id, name: String(p.name || '').slice(0, 200), url: p.url, price: num(p.price), rating: num(p.rating), review_count: num(p.review_count), size: sizeOf(p.name) };
  for (const f of Object.keys(MULTI)) row[f] = pickMany(f, it[f], text, p.id);
  for (const f of SINGLE) row[f] = pickOne(f, it[f], text, p.id);
  return row;
});

// Attribute summary used to GROUND the trend step: only values that really occur in this run's products
const attributeSummary = {};
const attributeCoverage = {};
for (const f of FACETS) {
  const tally = new Map();
  let known = 0;
  for (const row of standardized) {
    const vals = (Array.isArray(row[f]) ? row[f] : [row[f]]).filter((v) => v && v !== 'unknown' && v !== 'other');
    if (vals.length) known += 1;
    for (const v of vals) tally.set(v, (tally.get(v) || 0) + 1);
  }
  attributeSummary[f] = [...tally.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([value, count]) => ({ value, count, share_pct: Math.round((count / standardized.length) * 1000) / 10 }));
  attributeCoverage[f] = Math.round((known / standardized.length) * 100) / 100;
}
const prices = standardized.map((r) => r.price).filter((x) => x !== null && x > 0).sort((a, b) => a - b);
const priceStats = prices.length ? { n: prices.length, min: prices[0], median: prices[Math.floor((prices.length - 1) / 2)], max: prices[prices.length - 1] } : null;

// Course-shaped output (labels such as "Gray", "Low-pile", "$50-100"), computed from the validated data
const courseProducts = standardized.map((r) => ({
  url: r.url, name: r.name,
  attributes: { size: r.size, color: label('colors', r.colors[0]), material: label('material', r.material[0]), pattern: label('pattern', r.pattern),
    style: label('style', r.style), pile_height: label('pile', r.pile), price_bucket: bucketOf(r.price) },
  details: { id: r.id, price: r.price, rating: r.rating, review_count: r.review_count, colors: r.colors, materials: r.material, construction: r.construction,
    shape: r.shape, size_class: r.size_class, features: r.features },
}));
const top = (pick, n = 3) => {
  const t = new Map();
  for (const p of courseProducts) { const v = pick(p); if (v && v !== 'Unknown') t.set(v, (t.get(v) || 0) + 1); }
  return [...t.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, n).map(([v]) => v);
};
const topFeatures = (n = 3) => {
  const t = new Map();
  for (const p of courseProducts) for (const f of p.details.features) t.set(f, (t.get(f) || 0) + 1);
  return [...t.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, n).map(([v]) => label('features', v));
};
const ORDER = ['Under $50', '$50-100', '$100-200', '$200-500', '$500+'];
const price_distribution = {};
for (const b of ORDER) { const c = courseProducts.filter((p) => p.attributes.price_bucket === b).length; if (c) price_distribution[b] = c; }
const summary = {
  top_sizes: top((p) => p.attributes.size), top_colors: top((p) => p.attributes.color), top_materials: top((p) => p.attributes.material),
  top_patterns: top((p) => p.attributes.pattern), top_styles: top((p) => p.attributes.style), top_pile_heights: top((p) => p.attributes.pile_height),
  top_features: topFeatures(), price_distribution,
};
const attributeData = { products: courseProducts, summary };

return [{ json: { ...base, attributeData, products: courseProducts, summary, standardizedProducts: standardized, attributeSummary, attributeCoverage, priceStats, invalidValues: invalid, unsupportedValues: unsupported, unsupportedExamples } }];

// Save Trend List | Mode: Run Once for All Items
// Course interface: microSegments (name, description, visual_characteristics, color_palette, typical_materials,
// target_rooms, price_positioning, trend_signals, image_prompt_keywords) and segmentCount.
// The AI proposes segments; this node GROUNDS them in the evidence before anything moves on:
//  - attribute values must be in the vocabulary AND occur in this run's products; hashtags must have been supplied
//  - a product "matches" a segment only if it carries at least HALF of the segment's attribute groups (counted here)
//  - hashtags are kept only if they are relevant to the segment and are not generic community tags
//  - AI-written text is labelled ("AI note:") and sentences that claim demand or sales are removed
//  - segments that describe (almost) the same products are merged away
//  - price positioning is computed here; confidence can only be lowered by the evidence rules, never raised
//  - no segment is ever invented: if nothing survives, the run reports "no_segments"
const VOCAB = {"material":["wool","cotton","jute","polyester","polypropylene","nylon","viscose","microfiber","chenille","acrylic","faux_fur","blend","synthetic","other","unknown"],"construction":["flatweave","hand_tufted","machine_tufted","hand_knotted","power_loomed","braided","other","unknown"],"pile":["flat","low","medium","high","shag","unknown"],"colors":["cream","white","gray","charcoal","beige","taupe","brown","blue","navy","teal","green","red","orange","pink","purple","multi","black","gold","ivory","tan","olive","yellow","mustard","terracotta","other"],"pattern":["solid","geometric","floral","abstract","medallion","striped","moroccan","distressed","braided","textured","oriental","tribal","chevron","trellis","other","unknown"],"style":["modern","traditional","transitional","bohemian","farmhouse","coastal","minimalist","vintage","contemporary","industrial","mid_century","glam","rustic","other","unknown"],"shape":["rectangle","round","square","oval","runner","other","unknown"],"size_class":["small","medium","large","xl","runner","unknown"],"features":["washable","non_slip","stain_resistant","water_resistant","uv_resistant","indoor_outdoor","soft_plush","handmade","eco_friendly"]};
const FACETS = ['material', 'construction', 'pile', 'colors', 'pattern', 'style', 'features'];
const ALIASES = { pile: { flatweave: 'flat', low_pile: 'low', medium_pile: 'medium', high_pile: 'high' }, colors: { grey: 'gray', charcoal_gray: 'charcoal', charcoal_grey: 'charcoal' } };
const ROOMS = ['living room', 'bedroom', 'dining room', 'home office', 'nursery', 'kids room', 'entryway', 'hallway', 'kitchen', 'patio', 'balcony', 'deck'];
const POSITIONS = ['value', 'mid-range', 'premium'];
const LEVELS = ['low', 'medium', 'high'];
const MAX_SEGMENTS = 3;
const MIN_PRODUCTS_FOR_MEDIUM = 8;
const MAX_OVERLAP = 0.8;                         // segments sharing more than 80% of their products are merged
const GENERIC_TAGS = new Set(['#ruglovers', '#ruglove', '#rugstyle', '#rugsofinstagram', '#interiordesign', '#interior', '#interiors', '#homedecor', '#home',
  '#decor', '#livingroom', '#homeinspo', '#homemakeover', '#design', '#style', '#instahome']);
const TAG_SYNONYMS = { bohemian: ['boho'], boho: ['bohemian'], hand_tufted: ['handtufted', 'handmade'], handmade: ['handtufted', 'handknotted', 'handmade'], textured: ['texture'],
  minimalist: ['minimal'], mid_century: ['midcentury'], non_slip: ['nonslip'], vintage: ['retro'], gray: ['grey'], flatweave: ['flatweave', 'kilim'] };
const STOP = new Set(['rug', 'rugs', 'area', 'unknown', 'other', 'with', 'and', 'the']);
const DEMAND = /\b(?:demand|demanded|bestsell\w*|best-sell\w*|sales?|growing|growth|surge\w*|skyrocket\w*|booming|market size|market share)\b/i;
const title = (v) => (v === 'mid_century' ? 'Mid-Century' : v.split('_').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' '));

const std = $('Save Standardized Data').first().json;
const social = $('Merge All Data1').first().json.imageAnalysis?.trend_summary || {};
const products = std.standardizedProducts || [];
const warnings = Array.isArray(social.data_warnings) ? social.data_warnings : [];
const category = std.selectedCategory;
const out = (extra) => [{ json: { selectedCategory: category, categoryKey: std.categoryKey, trendStatus: 'ok', errorReason: null,
  microSegments: [], segmentCount: 0, overlap_dropped: [], data_warnings: warnings,
  basis: { products_analyzed: products.length, social_posts: social.total_posts_analyzed ?? 0 },
  ai_written_fields: ['description', 'visual_characteristics', 'image_prompt_keywords', 'trend_signals entries starting with "AI note:"'], ...extra } }];

if (products.length === 0) return out({ trendStatus: 'skipped', errorReason: std.errorReason || 'no_valid_products' });
const parseJson = (text) => {
  const t = String(text).replace(/```(?:json)?/gi, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
};
const ai = $input.first().json;
if (ai.error !== undefined || typeof ai.output !== 'string' || ai.output.trim() === '') return out({ trendStatus: 'ai_unavailable', errorReason: 'ai_unavailable' });
const parsed = parseJson(ai.output);
if (!parsed || !Array.isArray(parsed.micro_segments)) return out({ trendStatus: 'parse_failed', errorReason: 'ai_output_invalid' });

const asList = (v) => (Array.isArray(v) ? v : v == null || v === '' ? [] : [v]);
const norm = (f, v) => { const n = String(v).trim().toLowerCase().replace(/[\s-]+/g, '_'); return (ALIASES[f] && ALIASES[f][n]) || n; };
const clean = (s, max) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const present = {};
for (const f of FACETS) present[f] = new Set((std.attributeSummary?.[f] || []).map((e) => e.value));
const tagInfo = new Map();
for (const e of social.top_hashtags_by_engagement || []) tagInfo.set(e.tag, { tag: e.tag, count: e.count, engagement_share_pct: e.engagement_share_pct });
for (const e of social.top_hashtags || []) if (!tagInfo.has(e.tag)) tagInfo.set(e.tag, { tag: e.tag, count: e.count, engagement_share_pct: null });

// Words a hashtag must relate to: the segment name and its attribute values (plus synonyms)
const topicTokens = (name, attributes) => {
  const t = new Set();
  const add = (w) => { if (w.length >= 4 && !STOP.has(w)) t.add(w); };
  for (const w of name.toLowerCase().split(/[^a-z]+/)) { add(w); for (const s of TAG_SYNONYMS[w] || []) add(s); }
  for (const list of Object.values(attributes)) for (const v of list) {
    add(v.replace(/_/g, ''));
    for (const part of v.split('_')) if (part.length >= 5) add(part);
    for (const s of TAG_SYNONYMS[v] || []) add(s);
  }
  return t;
};
const relevantTag = (tag, tokens) => { const body = tag.slice(1); return [...tokens].some((w) => body.includes(w)); };

// Price terciles across all analysed products (for "value / mid-range / premium")
const allPrices = products.map((p) => p.price).filter((x) => x !== null && x > 0).sort((a, b) => a - b);
const q = (p) => allPrices[Math.floor((allPrices.length - 1) * p)];
const median = (arr) => { const s = [...arr].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)]; };
const jaccard = (a, b) => { const A = new Set(a), B = new Set(b); const inter = [...A].filter((x) => B.has(x)).length; const union = new Set([...A, ...B]).size; return union ? inter / union : 0; };

const seen = new Set();
const candidates = [];
for (const seg of parsed.micro_segments) {
  if (!seg || typeof seg !== 'object') continue;
  const name = clean(seg.name, 60);
  if (name.length < 2 || seen.has(name.toLowerCase())) continue;

  const attributes = {};
  for (const f of FACETS) {
    const vals = [];
    for (const v of asList(seg.attributes?.[f])) {
      const n = norm(f, v);
      if (VOCAB[f].includes(n) && present[f].has(n) && !vals.includes(n)) vals.push(n);
    }
    if (vals.length) attributes[f] = vals.slice(0, 3);
  }
  const defined = Object.keys(attributes);
  if (defined.length < 2) continue;                       // a segment needs a real combination of attributes

  // A product matches only if it carries at least half of the segment's attribute groups (and never fewer than 2)
  const required = Math.min(defined.length, Math.max(2, Math.ceil(defined.length / 2)));
  const matched = products.filter((p) => defined.filter((f) => asList(p[f]).some((v) => attributes[f].includes(v))).length >= required);

  const tokens = topicTokens(name, attributes);
  const hashtags = [];
  for (const h of asList(seg.hashtags ?? seg.evidence?.hashtags)) {
    const tag = `#${String(h).trim().toLowerCase().replace(/^#+/, '')}`;
    if (tagInfo.has(tag) && !GENERIC_TAGS.has(tag) && relevantTag(tag, tokens) && !hashtags.includes(tag)) hashtags.push(tag);
  }
  const support = hashtags.slice(0, 5).map((t) => tagInfo.get(t));

  const grounded = (f, list) => [...new Set(asList(list).map((v) => norm(f, v)).filter((v) => VOCAB[f].includes(v) && present[f].has(v)))].slice(0, 4).map(title);
  const matchedPrices = matched.map((p) => p.price).filter((x) => x !== null && x > 0);
  let position = POSITIONS.includes(seg.price_positioning) ? seg.price_positioning : 'mid-range';
  if (allPrices.length >= 3 && matchedPrices.length) {
    const m = median(matchedPrices);
    position = m <= q(0.33) ? 'value' : m >= q(0.67) ? 'premium' : 'mid-range';
  }
  const aiNotes = asList(seg.trend_signals).map((s) => clean(s, 150)).filter((s) => s && !DEMAND.test(s)).slice(0, 2).map((s) => `AI note: ${s}`);
  const signals = [`${matched.length} of ${products.length} analysed products match at least ${required} of this segment's ${defined.length} attribute groups`,
    ...support.slice(0, 2).map((h) => `${h.tag} is among the top social hashtags${h.engagement_share_pct != null ? ` (${h.engagement_share_pct}% engagement share)` : ''}`),
    ...aiNotes].slice(0, 5);
  const description = clean(String(seg.description ?? '').split(/(?<=[.!?])\s+/).filter((s) => !DEMAND.test(s)).join(' '), 300);

  let level = LEVELS.includes(String(seg.confidence).toLowerCase()) ? String(seg.confidence).toLowerCase() : 'low';
  const cap = matched.length < 2 ? 'low' : (products.length < MIN_PRODUCTS_FOR_MEDIUM || warnings.length > 0 ? 'medium' : 'high');
  if (LEVELS.indexOf(level) > LEVELS.indexOf(cap)) level = cap;

  seen.add(name.toLowerCase());
  candidates.push({
    ids: matched.map((p) => p.id),
    segment: {
      name, description,
      visual_characteristics: asList(seg.visual_characteristics).map((s) => clean(s, 60)).filter(Boolean).slice(0, 5),
      color_palette: grounded('colors', seg.color_palette), typical_materials: grounded('material', seg.typical_materials),
      target_rooms: [...new Set(asList(seg.target_rooms).map((r) => clean(r, 30).toLowerCase()).filter((r) => ROOMS.includes(r)))].slice(0, 3),
      price_positioning: position, trend_signals: signals,
      image_prompt_keywords: [...new Set(asList(seg.image_prompt_keywords).map((k) => String(k).toLowerCase().replace(/[^a-z0-9 -]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 30)).filter((k) => k.length >= 3))].slice(0, 6),
      attributes, evidence: { matching_products: matched.length, required_attribute_groups: required, products_analyzed: products.length, hashtag_support: support }, confidence: level,
    },
  });
}

// Best supported first; then drop segments that cover (almost) the same products as one already kept
candidates.sort((a, b) => b.ids.length - a.ids.length || b.segment.evidence.hashtag_support.length - a.segment.evidence.hashtag_support.length);
const kept = [];
const overlapDropped = [];
for (const c of candidates) {
  const clash = kept.map((k) => ({ k, o: jaccard(k.ids, c.ids) })).find((x) => x.o > MAX_OVERLAP);
  if (clash) overlapDropped.push({ dropped: c.segment.name, overlaps_with: clash.k.segment.name, overlap_pct: Math.round(clash.o * 100) });
  else kept.push(c);
}
const top = kept.slice(0, MAX_SEGMENTS).map((c, i) => {
  const others = kept.filter((k) => k !== c).map((k) => jaccard(k.ids, c.ids));
  return { rank: i + 1, ...c.segment, evidence: { ...c.segment.evidence, max_overlap_with_other_segments_pct: Math.round((others.length ? Math.max(...others) : 0) * 100) } };
});
return out({ trendStatus: top.length ? 'ok' : 'no_segments', errorReason: top.length ? null : 'no_segments', microSegments: top, segmentCount: top.length, overlap_dropped: overlapDropped });

// Split Segments for Images | Mode: Run Once for All Items
// Course interface: one item per micro-segment as { segment }. With no segment: { segment: null, skip: true },
// plus the reason, so "Check Segment Exists" can route it to the error response.
const trend = $input.first().json;
const segments = Array.isArray(trend.microSegments) ? trend.microSegments : [];
const common = { category: trend.selectedCategory ?? null, categoryKey: trend.categoryKey ?? null, data_warnings: trend.data_warnings || [] };

if (segments.length === 0) {
  const reason = trend.errorReason
    || $('Save Standardized Data').first().json.errorReason
    || $('Remove Invalid Products').first().json.errorReason
    || 'no_segments';
  return [{ json: { segment: null, skip: true, segment_index: null, total_segments: 0, errorReason: reason, ...common } }];
}
return segments.map((segment, i) => ({
  pairedItem: { item: 0 },
  json: { segment, skip: false, segment_index: i, total_segments: segments.length, errorReason: null, ...common },
}));
